#!/bin/zsh
# 让 Codex 出「从链接导入时直接登录」的设计稿：每条认出来的链接旁边显示登录状态，要登录的直接给登录按钮。
cd "$(dirname "$0")"
name=ui_link_login
[ -f "$name.png" ] && exit 0
P="当前目录有 ref_link_current.jpg，是 macOS 应用「豆仓」现在的「从链接导入」窗口截图（已定稿的配色：暖灰底、石墨黑文字、唯一强调色玫瑰红 #F43F5E、绿色只表示已连接/已登录）。请先看这张图，然后使用内置的 image_gen 工具（把它一起传入，保持风格、字体、圆角、间距完全一致）生成一张 16:10 横向的高保真 UI 设计稿（正视图、不要透视）：画面和参考图同样的布局，背景的豆仓窗口略微压暗，正中是「从链接导入」表单窗口。输入框里贴着三条链接（小红书、视频号、抖音）。输入框下面的识别列表里每条一行：左边玫瑰红小方块播放图标、平台名、灰色短链接；行尾不再是统一的绿勾，而是这条链接所在平台的登录状态：①「小红书」行尾是一个玫瑰红描边的小胶囊按钮「登录」，按钮左边一个淡玫瑰底的小标签「要先登录」；这一行下面缩进一行很小的灰字「这台 Mac 走的是海外网络，小红书要登录才给看笔记。会直接打开这条笔记，在页面上登录。」②「视频号」行尾是绿色小字「已登录」加一个绿色小勾；③「抖音」行尾也是绿色「已登录」加小勾。列表下方一行小灰字「只导入你有权保存的公开内容。下载下来的只有声音，用来转成文字。」；底部右侧两个按钮：次要的「取消」和玫瑰红主按钮「导入 3 条」。整体克制、对齐严谨，像苹果设计奖级别的 macOS 应用。界面文字全部是简体中文，像苹方，清晰可读、没有乱码。绝对不要蓝色、紫色、琥珀橙。生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。"
t0=$(date +%s)
codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write "$P" < /dev/null > "$name.log" 2>&1
echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
